create extension if not exists pgcrypto;
create table users(id uuid primary key default gen_random_uuid(),name varchar(100) not null,email varchar(255) not null unique,password_hash varchar(255) not null,date_of_birth date not null,role varchar(40) not null,mfa_enabled boolean not null default false,mfa_secret varchar(512),guardian_approved boolean not null default false,active boolean not null default true,created_at timestamptz not null);
create table consents(id uuid primary key default gen_random_uuid(),user_id uuid not null references users(id),persona_id varchar(120) not null,interactive_allowed boolean not null default false,voice_allowed boolean not null default false,avatar_allowed boolean not null default false,text_allowed boolean not null default false,withdrawn boolean not null default false,version integer not null default 1,updated_at timestamptz not null,unique(user_id,persona_id));
